#!/usr/bin/env python3
"""Build the generated BY_YEAR view for movie and show catalogs."""

from __future__ import annotations

import argparse
import csv
import json
import os
import re
import sys
from datetime import date
from pathlib import Path

# Keep the generated media view free of interpreter cache artifacts.
sys.dont_write_bytecode = True

from catalog_config import (
    MOVIE_SOURCES,
    SHOW_IMDB_IDS,
    SHOW_SOURCES,
    catalog_item_label,
    catalog_movie_items,
)
from imdb_index import (
    SeriesCandidate,
    ensure_imdb_index,
    load_imdb_series_matches,
    normalized_title,
)
from paths import add_root_argument, require_library_root, state_dir
from show_years import load_show_release_years


YEAR_VIEW = "BY_YEAR"
YEAR_RE = re.compile(r"\(((?:18|19|20)\d{2})\)")
SHOW_YEAR_RE = re.compile(r"^(?P<title>.+?)\s+\((?P<year>(?:18|19|20)\d{2})\)$")


def relative_link_target(link: Path, target: Path) -> str:
    return os.path.relpath(target, start=link.parent)


def movie_year(path: Path) -> int | None:
    matches = list(YEAR_RE.finditer(catalog_item_label(path)))
    return int(matches[-1].group(1)) if matches else None


def movie_items(
    library_root: Path,
) -> list[tuple[Path, Path, int]]:
    items: list[tuple[Path, Path, int]] = []
    for relative_source in MOVIE_SOURCES:
        source = library_root / relative_source
        if not source.is_dir():
            print(f"warning: source directory is missing: {source}", file=sys.stderr)
            continue
        for path in catalog_movie_items(source):
            year = movie_year(path)
            if year is None:
                print(
                    f"warning: movie has no parenthesized year: "
                    f"{path.relative_to(library_root)}",
                    file=sys.stderr,
                )
                continue
            items.append((path, path.relative_to(source), year))
    return sorted(items, key=lambda item: str(item[0]).casefold())


def show_items(
    library_root: Path,
) -> list[tuple[Path, str, int | None]]:
    items: list[tuple[Path, str, int | None]] = []
    for relative_source in SHOW_SOURCES:
        source = library_root / relative_source
        if not source.is_dir():
            print(f"warning: show source directory is missing: {source}", file=sys.stderr)
            continue
        for path in source.iterdir():
            if not path.is_dir() or path.is_symlink():
                continue
            match = SHOW_YEAR_RE.fullmatch(path.name)
            if match:
                title = match.group("title")
                hinted_year = int(match.group("year"))
            else:
                title = path.name
                hinted_year = None
            items.append((path, normalized_title(title), hinted_year))
    return sorted(items, key=lambda item: str(item[0]).casefold())


def select_series_match(
    candidates: list[SeriesCandidate],
    hinted_year: int | None,
) -> SeriesCandidate | None:
    if hinted_year is not None:
        candidates = [
            candidate for candidate in candidates if candidate[2] == hinted_year
        ]
    if not candidates:
        return None

    def score(candidate: SeriesCandidate) -> tuple[int, int]:
        match_method = candidate[5]
        return (
            int(match_method == "imdb-series-title"),
            candidate[4],
        )

    best_score = max(score(candidate) for candidate in candidates)
    best = [candidate for candidate in candidates if score(candidate) == best_score]
    return best[0] if len(best) == 1 else None


def indexed_year_links(row: dict[str, str], genres_root: Path) -> list[Path]:
    encoded_paths = row.get("generated_links", "")
    relative_paths = json.loads(encoded_paths)
    if not isinstance(relative_paths, list) or not all(
        isinstance(path, str) for path in relative_paths
    ):
        raise RuntimeError("invalid generated_links value in year index")

    links: list[Path] = []
    for value in relative_paths:
        relative = Path(value)
        if (
            relative.is_absolute()
            or len(relative.parts) < 4
            or ".." in relative.parts
            or relative.parts[0] != YEAR_VIEW
            or not relative.parts[1].isdigit()
            or len(relative.parts[1]) != 4
            or relative.parts[2] not in {"Movies", "Shows"}
        ):
            raise RuntimeError(
                f"unsafe generated year-link path in year index: {value!r}"
            )
        links.append(genres_root / relative)
    return links


def load_owned_links(
    index_path: Path,
    genres_root: Path,
    library_root: Path,
) -> dict[Path, Path]:
    owned: dict[Path, Path] = {}
    if not index_path.is_file():
        return owned
    with index_path.open(encoding="utf-8", newline="") as source:
        for row in csv.DictReader(source, delimiter="\t"):
            target = library_root / row["source"]
            for link in indexed_year_links(row, genres_root):
                owned[link] = target
    return owned


def generated_container_is_replaceable(
    path: Path,
    old_owned: dict[Path, Path],
) -> bool:
    """Return whether a directory contains only old generated symlinks."""

    if not path.is_dir() or path.is_symlink():
        return False
    found_owned_link = False
    for child in path.rglob("*"):
        if child.is_symlink():
            target = old_owned.get(child)
            if (
                target is None
                or child.resolve(strict=False) != target.resolve(strict=False)
            ):
                return False
            found_owned_link = True
        elif child.is_file():
            return False
    return found_owned_link


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Rebuild BY_YEAR links for movie and show catalogs."
    )
    add_root_argument(parser)
    parser.add_argument(
        "--imdb-data",
        type=Path,
        help="path to title.basics.tsv.gz",
    )
    parser.add_argument(
        "--imdb-akas",
        type=Path,
        help="path to title.akas.tsv.gz",
    )
    parser.add_argument(
        "--imdb-episodes",
        type=Path,
        help="path to title.episode.tsv.gz",
    )
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="report the result without changing links or the index",
    )
    args = parser.parse_args()
    library_root = require_library_root(parser, args.root)
    genres_root = library_root / "genres"
    data_dir = state_dir(library_root)
    imdb_data = args.imdb_data or data_dir / "title.basics.tsv.gz"
    imdb_akas = args.imdb_akas or data_dir / "title.akas.tsv.gz"
    imdb_episodes = args.imdb_episodes or data_dir / "title.episode.tsv.gz"

    for path in (imdb_data, imdb_akas):
        if not path.is_file():
            parser.error(f"IMDb data file not found: {path}")

    imdb_index = data_dir / "imdb-index.sqlite3"
    ensure_imdb_index(
        imdb_data,
        imdb_akas,
        imdb_index,
        allow_build=not args.dry_run,
    )

    movies = movie_items(library_root)
    shows = show_items(library_root)
    series_matches = load_imdb_series_matches(
        imdb_index, {title for _, title, _ in shows}
    )
    current_year = date.today().year

    resolved_shows: list[
        tuple[Path, list[SeriesCandidate], str]
    ] = []
    skipped_shows = 0
    wanted_series_ids: set[str] = set()
    for show, title, hinted_year in shows:
        relative_show = str(show.relative_to(library_root))
        candidates = series_matches.get(title, [])
        override_ids = SHOW_IMDB_IDS.get(relative_show)
        if override_ids is not None:
            selected = [
                candidate
                for imdb_id in override_ids
                for candidate in candidates
                if candidate[0] == imdb_id
            ]
            match_method = "catalog-imdb-override"
            if len(selected) != len(override_ids):
                selected = []
        else:
            match = select_series_match(candidates, hinted_year)
            selected = [match] if match is not None else []
            match_method = selected[0][5] if selected else ""

        if not selected:
            skipped_shows += 1
            qualifier = (
                f" with start-year hint {hinted_year}"
                if hinted_year is not None
                else ""
            )
            print(
                f"warning: no unique IMDb series match for "
                f"{show.relative_to(library_root)}{qualifier}",
                file=sys.stderr,
            )
            continue
        resolved_shows.append((show, selected, match_method))
        wanted_series_ids.update(candidate[0] for candidate in selected)

    exact_show_years = load_show_release_years(
        imdb_data,
        imdb_episodes,
        data_dir / "show-years-cache.json",
        wanted_series_ids,
        allow_build=not args.dry_run,
    )

    desired: dict[Path, Path] = {}
    rows: list[tuple[str, ...]] = []
    matched_shows = 0
    movie_collections: dict[Path, set[int]] = {}

    for movie, relative_in_source, year in movies:
        if len(relative_in_source.parts) > 1:
            source_root = movie.parents[len(relative_in_source.parts) - 1]
            collection = source_root / relative_in_source.parts[0]
            movie_collections.setdefault(collection, set()).add(year)
            relative_link = (
                Path(YEAR_VIEW)
                / str(year)
                / "Movies"
                / relative_in_source.parts[0]
            )
            link = genres_root / relative_link
            previous = desired.get(link)
            if previous is not None and previous != collection:
                raise RuntimeError(
                    f"duplicate generated year-link path for {relative_link}: "
                    f"{previous} and {collection}"
                )
            desired[link] = collection
            continue

        relative_link = Path(YEAR_VIEW) / str(year) / "Movies" / relative_in_source
        link = genres_root / relative_link
        previous = desired.get(link)
        if previous is not None and previous != movie:
            raise RuntimeError(
                f"duplicate generated year-link path for {relative_link}: "
                f"{previous} and {movie}"
            )
        desired[link] = movie
        rows.append(
            (
                "movie",
                str(movie.relative_to(library_root)),
                catalog_item_label(movie),
                str(year),
                "",
                "",
                "filename-year",
                json.dumps(
                    [str(relative_link)],
                    ensure_ascii=False,
                    separators=(",", ":"),
                ),
            )
        )

    for collection, years in sorted(
        movie_collections.items(), key=lambda item: str(item[0]).casefold()
    ):
        relative_links = [
            str(Path(YEAR_VIEW) / str(year) / "Movies" / collection.name)
            for year in sorted(years)
        ]
        rows.append(
            (
                "movie-collection",
                str(collection.relative_to(library_root)),
                collection.name,
                ",".join(str(year) for year in sorted(years)),
                "",
                "",
                "catalog-collection-years",
                json.dumps(
                    relative_links,
                    ensure_ascii=False,
                    separators=(",", ":"),
                ),
            )
        )

    for show, selected, match_method in resolved_shows:
        years = sorted(
            {
                year
                for candidate in selected
                for year in exact_show_years.get(candidate[0], ())
                if year <= current_year
            }
        )
        if not years:
            span_years: set[int] = set()
            for candidate in selected:
                start_year, end_year = candidate[2], candidate[3]
                last_year = (
                    min(end_year, current_year)
                    if end_year is not None
                    else current_year
                )
                if start_year > last_year or last_year - start_year > 150:
                    continue
                span_years.update(range(start_year, last_year + 1))
            years = sorted(span_years)
            if years:
                print(
                    f"warning: using IMDb series span instead of exact episode "
                    f"years for {show.relative_to(library_root)}",
                    file=sys.stderr,
                )
        if not years:
            skipped_shows += 1
            print(
                f"warning: no safe release years for "
                f"{show.relative_to(library_root)}",
                file=sys.stderr,
            )
            continue

        relative_links: list[str] = []
        for year in years:
            relative_link = Path(YEAR_VIEW) / str(year) / "Shows" / show.name
            link = genres_root / relative_link
            previous = desired.get(link)
            if previous is not None and previous != show:
                raise RuntimeError(
                    f"duplicate generated year-link path for {relative_link}: "
                    f"{previous} and {show}"
                )
            desired[link] = show
            relative_links.append(str(relative_link))

        rows.append(
            (
                "show",
                str(show.relative_to(library_root)),
                show.name,
                ",".join(str(year) for year in years),
                ",".join(candidate[0] for candidate in selected),
                " / ".join(candidate[1] for candidate in selected),
                match_method,
                json.dumps(
                    relative_links,
                    ensure_ascii=False,
                    separators=(",", ":"),
                ),
            )
        )
        matched_shows += 1

    index_path = genres_root / "_year-index.tsv"
    old_owned = load_owned_links(index_path, genres_root, library_root)

    # Refuse collisions before removing any link owned by the previous build.
    for link, target in desired.items():
        if not (link.exists() or link.is_symlink()):
            continue
        old_target = old_owned.get(link)
        if (
            old_target is not None
            and link.is_symlink()
            and link.resolve(strict=False) == old_target.resolve(strict=False)
        ):
            continue
        if generated_container_is_replaceable(link, old_owned):
            continue
        raise FileExistsError(f"refusing to replace existing path: {link}")

    if args.dry_run:
        print(
            f"Would index {len(movies)} movies and {matched_shows} shows "
            f"with {len(desired)} BY_YEAR symlinks; "
            f"{skipped_shows} shows skipped."
        )
        return 0

    old_link_parents: set[Path] = set()
    for link, target in old_owned.items():
        if (
            link.is_symlink()
            and link.resolve(strict=False) == target.resolve(strict=False)
        ):
            link.unlink()
            old_link_parents.add(link.parent)

    for directory in sorted(
        old_link_parents, key=lambda path: len(path.parts), reverse=True
    ):
        while directory != genres_root and directory.parent != genres_root:
            try:
                directory.rmdir()
            except OSError:
                break
            directory = directory.parent

    for link, target in desired.items():
        link.parent.mkdir(parents=True, exist_ok=True)
        if link.exists() or link.is_symlink():
            raise FileExistsError(f"refusing to replace existing path: {link}")
        link.symlink_to(relative_link_target(link, target))

    temporary_index = index_path.with_suffix(index_path.suffix + ".new")
    with temporary_index.open("w", encoding="utf-8", newline="") as destination:
        writer = csv.writer(destination, delimiter="\t", lineterminator="\n")
        writer.writerow(
            (
                "kind",
                "source",
                "title",
                "years",
                "imdb_id",
                "imdb_title",
                "match_method",
                "generated_links",
            )
        )
        writer.writerows(rows)
    temporary_index.replace(index_path)

    print(
        f"Indexed {len(movies)} movies and {matched_shows} shows "
        f"with {len(desired)} BY_YEAR symlinks; "
        f"{skipped_shows} shows skipped."
    )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
